[
  {
    "title": "pre-fight-input-guide",
    "claim": "The qualifier card shows STANCE and TECHNIQUE beneath directional chevrons, but omits the action guide visible in the fight frame.",
    "reason": "The introduction is a useful place to explain what each direction does before the player needs it.",
    "suggest": "Reuse the fight frame’s directional action guide on the qualifier card, with readable labels and no overlap with the Fight button."
  },
  {
    "title": "record-clock-label",
    "claim": "The Asmongold win-result frame displays 29s on the round timer and FASTEST WIN 6.1S without identifying the record’s time basis.",
    "reason": "These values are not necessarily contradictory, but players cannot tell whether the record includes introductions or referee pauses.",
    "suggest": "Verify which clock supplies the record, then explicitly label it as elapsed time or fighting time; do not change either value based on this still."
  },
  {
    "title": "result-pose-separation",
    "claim": "Both pictured win-result screens show the declared winner striking an opponent who remains in a fighting stance.",
    "reason": "At these captured moments, the character tableau still depicts contact rather than a distinct victory or defeat.",
    "suggest": "Retain the scoring pose for the impact moment, then use a distinct victory-and-defeat or bow tableau alongside the result panel; verify the existing transition before changing it."
  },
  {
    "title": "desktop-keyboard-discovery",
    "claim": "The desktop fight frame displays two touch-stick controls but no visible keyboard bindings.",
    "reason": "A desktop player cannot discover the keyboard mapping from this screen.",
    "suggest": "Place a compact keyboard legend between the sticks, populated from the actual input bindings, while retaining the touch controls."
  },
  {
    "title": "metadata-size-unverified",
    "claim": "The techniques sheet renders scoring metadata visibly smaller than move names, but the raster image cannot establish its computed CSS font size.",
    "reason": "Relative size alone does not prove a violation of the project’s 18 CSS px readability minimum.",
    "suggest": "Measure the metadata’s computed font size at the supplied phone viewport; increase any text below 18 CSS px and wrap the rows rather than shrinking their contents."
  }
]
